var HC_EV_NM=1239.841984; // eV·nm
var C_MS=2.99792458e8;    // m/s
var RYDBERG=1.0973731568508e7; // 1/m
function eVfromNm(nm){ return HC_EV_NM/nm; }
function nmFromEV(eV){ return HC_EV_NM/eV; }
function nuFromNm(nm){ return C_MS/(nm*1e-9); }
function band(nm){
  if(nm<0.01) return "γ 射线";
  if(nm<10) return "X 射线";
  if(nm<400) return "紫外";
  if(nm<=700) return "可见光";
  if(nm<1e6) return "红外"; // 700nm ~ 1mm
  if(nm<1e9) return "微波";
  return "无线电波";
}
function hydrogenLine(n2){ // Balmer n1=2
  if(n2<=2) return null;
  var inv=RYDBERG*(1/4 - 1/(n2*n2)); return 1/inv*1e9; // nm
}
var EXPORTS={eVfromNm:eVfromNm, nmFromEV:nmFromEV, nuFromNm:nuFromNm, band:band, hydrogenLine:hydrogenLine, HC_EV_NM:HC_EV_NM};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpectroscopyForgePure = EXPORTS; }
